import{_ as i,C as n,o,c as d,aj as t,E as s}from"./framework.js";const u=JSON.parse('{"title":"Inline Edit | Site | Admin CMS","description":"Click elements directly on the front-end rendered result to change them. It is suitable for copy, images, links, and local styles without writing HTML by hand. Saving writes back to the…","frontmatter":{"title":"Inline Edit | Site | Admin CMS","description":"Click elements directly on the front-end rendered result to change them. It is suitable for copy, images, links, and local styles without writing HTML by hand. Saving writes back to the…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/site/pages-inline-edit.html"}]]},"headers":[],"relativePath":"cms/site/pages-inline-edit.md","filePath":"en/cms/site/pages-inline-edit.md","lastUpdated":1781010536000}'),r={name:"cms/site/pages-inline-edit.md"};function l(h,e,c,g,p,m){const a=n("DocImage");return o(),d("div",null,[e[0]||(e[0]=t('<h1 id="inline-edit" tabindex="-1">Inline Edit <a class="header-anchor" href="#inline-edit" aria-label="Permalink to &quot;Inline Edit&quot;">​</a></h1><blockquote><p>Open from <a href="./pages.html">Pages</a> row <strong>Inline Edit</strong><br> Deep link: <code>/_Admin/inline-design?SiteId={siteGuid}&amp;path={pagePath}&amp;id={pageId}&amp;type={pageType}</code></p></blockquote><p>Click elements directly on the <strong>front-end rendered result</strong> to change them. It is suitable for copy, images, links, and local styles without writing HTML by hand. Saving writes back to the corresponding Page (or design page) resource.</p><div class="tip custom-block"><p class="custom-block-title">Compared with Edit Code</p><table tabindex="0"><thead><tr><th></th><th>Inline Edit</th><th><a href="./pages-edit-code.html">Edit Code</a></th></tr></thead><tbody><tr><td>Scenario</td><td>Operational copy changes, image swaps, style adjustments</td><td>Structure, Layout placeholders, Views</td></tr><tr><td>UI</td><td>Embedded browser page + floating toolbar</td><td>Full-screen Monaco</td></tr></tbody></table></div><h2 id="how-to-open" tabindex="-1">How to open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to open&quot;">​</a></h2><ol><li><strong>Pages</strong> list -&gt; target row -&gt; <strong>Inline Edit</strong> (pencil icon).</li><li>It usually opens <code>/_Admin/inline-design</code> in a new window or full-screen layer with the current page <code>path</code>, <code>id</code>, <code>type</code>, and <code>SiteId</code>.</li><li>When the preview URL is requested, parameters such as <code>koobooInline=design</code> are appended, and an edit layer is overlaid on the page.</li></ol>',6)),s(a,{src:"/cms/site/pages-inline-edit.png",alt:"Inline Edit: preview page and floating toolbar",width:"1120"}),e[1]||(e[1]=t('<h2 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Description</th></tr></thead><tbody><tr><td>Main screen</td><td>Site page preview (the same as visitors see, including published content)</td></tr><tr><td>Element highlight</td><td>Border shown when the mouse enters or selects it (DomBorder)</td></tr><tr><td>Right floating toolbar</td><td>Draggable: undo/redo, save, viewport width, global style/color/image/link/text, and more</td></tr><tr><td>Context menu</td><td>Shown according to the selected node type (edit text, image, link, component, content, repeater, etc.)</td></tr><tr><td>Text floating bar</td><td>Appears when text is selected: bold, color, link, image, and other quick actions</td></tr></tbody></table><p>The site&#39;s <strong>Inline Edit settings</strong> (<code>inlineDesignSettings</code>) can disable some global buttons such as color, image, and link, depending on your environment.</p><h2 id="common-actions" tabindex="-1">Common actions <a class="header-anchor" href="#common-actions" aria-label="Permalink to &quot;Common actions&quot;">​</a></h2><h3 id="edit-text" tabindex="-1">Edit text <a class="header-anchor" href="#edit-text" aria-label="Permalink to &quot;Edit text&quot;">​</a></h3><ol><li>Double-click or select a text area.</li><li>Use the floating <strong>text toolbar</strong> or right-click <strong>Edit text</strong>.</li><li>Confirm after editing; the change enters the undo stack.</li></ol><h3 id="edit-images-and-links" tabindex="-1">Edit images and links <a class="header-anchor" href="#edit-images-and-links" aria-label="Permalink to &quot;Edit images and links&quot;">​</a></h3><ul><li>Right-click the corresponding element, or choose image/link from the floating bar.</li><li>Images can be selected from the <a href="./media.html">Media library</a> through the embedded media dialog.</li><li>Links can be internal paths or external URLs.</li></ul><h3 id="edit-styles" tabindex="-1">Edit styles <a class="header-anchor" href="#edit-styles" aria-label="Permalink to &quot;Edit styles&quot;">​</a></h3><ul><li>Right-click <strong>Edit style</strong>, or select an element and change CSS in the dialog.</li><li>Design page types may provide a <strong>Global Style</strong> entry (the page icon on the floating toolbar).</li></ul><h3 id="undo-save" tabindex="-1">Undo / Save <a class="header-anchor" href="#undo-save" aria-label="Permalink to &quot;Undo / Save&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Description</th></tr></thead><tbody><tr><td>Undo / Redo</td><td>Marked on the floating bar; some menus prompt you to save first when there are unsaved changes</td></tr><tr><td>Save</td><td>Available when there are changes; after saving, the preview refreshes in about 0.5 seconds to apply the result</td></tr></tbody></table><p>Saving writes DOM changes back to the server Page body.</p><h3 id="viewport-width" tabindex="-1">Viewport width <a class="header-anchor" href="#viewport-width" aria-label="Permalink to &quot;Viewport width&quot;">​</a></h3><p>The floating bar&#39;s <strong>screen size</strong> switches between common widths (desktop/tablet/phone) for responsive checks; it does not change the real URL.</p><h2 id="designer-pages" tabindex="-1">Designer pages <a class="header-anchor" href="#designer-pages" aria-label="Permalink to &quot;Designer pages&quot;">​</a></h2><p>If the page <code>type</code> is <strong>Designer</strong>, inline edit loads the visual page designer data, and the floating bar may add <strong>Global Style</strong> and similar items. For these pages, the main list entry is usually <strong>Design</strong>; inline edit is an additional preview-state entry.</p><h2 id="permissions-and-limits" tabindex="-1">Permissions and limits <a class="header-anchor" href="#permissions-and-limits" aria-label="Permalink to &quot;Permissions and limits&quot;">​</a></h2><ul><li>Requires the <code>pages</code> <strong>edit</strong> permission.</li><li>Complex structures (large amounts of script logic, dynamic lists) are often better edited in <a href="./pages-edit-code.html">Edit Code</a>.</li><li>With unsaved undo history, some &quot;apply immediately&quot; CMS edits (such as Labels) may be blocked and prompt you to save first.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./pages-setting.html">Page settings</a></td><td>URL, publish, Meta</td></tr><tr><td><a href="./pages-edit-code.html">Edit code</a></td><td>Body source</td></tr><tr><td><a href="/kb-docs/templateEngine/binding/">Template Engine · Binding</a></td><td>Relationship between <code>k-content</code> and inline edit</td></tr></tbody></table>',21))])}const f=i(r,[["render",l]]);export{u as __pageData,f as default};
